"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["58779"],{84698(e){e.exports=JSON.parse('{"id":"V4-074","slug":"non-gaap-measure","term":"Non-GAAP Measure","also_known_as":[],"difficulty":"Advanced","definition":"A non-GAAP measure is a financial figure reported by a company that is not defined by the official accounting standards, such as adjusted earnings, adjusted EBITDA or free cash flow, typically excluding certain items management considers unusual or non-cash.","explanation":["Companies often present non-GAAP or alternative performance measures alongside their official results, arguing that they better reflect underlying performance. Common adjustments exclude restructuring costs, acquisition-related costs, share-based compensation, impairments and the amortization of intangible assets from acquisitions.","For example, a company might report a statutory net profit of 50,000,000 and an adjusted profit of 80,000,000, after excluding 20,000,000 of restructuring costs and 10,000,000 of amortization from acquired intangibles.","These measures can be useful, but they can also present an overly favourable picture. Companies choose what to exclude, sometimes removing costs that recur every year.","Regulators set rules for how non-GAAP measures are presented. In the United States, the Securities and Exchange Commission requires companies to reconcile them to the closest official measure and not give them more prominence. European regulators have similar guidelines for alternative performance measures. Investors should always compare non-GAAP figures with official results and examine each adjustment."],"note":"","total":1725,"prev":{"slug":"non-fungible-token","term":"Non-Fungible Token (NFT)"},"next":{"slug":"non-operating-asset","term":"Non-Operating Asset"}}')}}]);